<template>
  <div dir="rtl">
    <div class="d-flex align-center flex-wrap ga-3 mb-5"><h1 class="text-h4">بوابات الدفع الإلكتروني</h1><v-spacer /><v-btn :loading="busy" @click="load">تحديث</v-btn><v-btn color="primary" @click="edit()">إضافة حساب</v-btn></div>
    <v-alert v-if="error" type="error" class="mb-4">{{ error }}</v-alert>
    <v-alert type="info" variant="tonal" class="mb-4">حسابات الدفع مستقلة حسب الشركة. يستخدم المتجر حسابات المنصة فقط. اكتمال بيانات الحساب لا يعني نجاح اختبار sandbox أو تفعيل حساب إنتاجي لدى المزود.</v-alert>
    <v-table><thead><tr><th>الحساب</th><th>المزود</th><th>البيئة</th><th>الإعداد</th><th>الحالة</th><th></th></tr></thead><tbody><tr v-for="gateway in gateways" :key="gateway.id"><td>{{ gateway.name }} <v-chip v-if="gateway.is_default" size="small">الافتراضي</v-chip></td><td>{{ gateway.driver }}</td><td>{{ gateway.is_test_mode ? 'اختبار' : 'إنتاج' }}</td><td>{{ gateway.ready ? 'مكتمل الإعداد' : 'غير مكتمل' }}</td><td>{{ gateway.is_active ? 'مفعل' : 'معطل' }}</td><td><v-btn variant="text" @click="edit(gateway)">تعديل</v-btn><v-btn variant="text" :disabled="busy || !gateway.is_active || gateway.is_default" @click="setDefault(gateway)">تعيين افتراضي</v-btn><v-btn color="error" variant="text" @click="deleting = gateway">حذف الحساب</v-btn></td></tr></tbody></v-table>
    <v-dialog v-model="dialog" max-width="720" scrollable><v-card><v-card-title>{{ form.id ? 'تعديل حساب الدفع' : 'إضافة حساب دفع' }}</v-card-title><v-card-text><v-form id="gateway-form" @submit.prevent="save"><v-text-field v-model="form.name" aria-label="اسم الحساب" label="اسم الحساب" required /><v-select v-model="form.driver" :items="drivers" item-title="name" item-value="id" aria-label="المزود" label="المزود" :disabled="!!form.id" @update:model-value="form.config = {}" /><v-switch v-model="form.is_test_mode" aria-label="حساب sandbox / اختبار" label="حساب sandbox / اختبار" /><v-switch v-model="form.is_active" aria-label="مفعل لقبول المدفوعات" label="مفعل لقبول المدفوعات" /><v-checkbox v-model="form.is_default" :disabled="!form.is_active" aria-label="الحساب الافتراضي" label="الحساب الافتراضي" /><template v-for="(kind,key) in definition?.fields" :key="key"><v-text-field v-model="form.config[key]" :label="labels[key] || key" :type="kind === 'secret' ? 'password' : 'text'" :hint="kind === 'secret' && configured[key] ? 'محفوظ؛ اتركه فارغًا للاحتفاظ به. لا يعاد السر من الخادم.' : (definition.required?.includes(key) ? 'مطلوب لتفعيل الحساب' : 'اختياري')" persistent-hint autocomplete="new-password" /></template><v-alert type="info" variant="tonal" class="mt-4">استعمل حسابًا جديدًا عند تغيير المزود أو مالك الحساب. تحفظ المعاملات إعدادات حسابها حتى يظل الاستعلام والاسترداد مرتبطين بالحساب الأصلي.</v-alert></v-form></v-card-text><v-card-actions><v-btn @click="dialog = false">إلغاء</v-btn><v-btn form="gateway-form" type="submit" color="primary" :loading="busy">حفظ</v-btn></v-card-actions></v-card></v-dialog>
    <v-dialog :model-value="!!deleting" max-width="500" @update:model-value="deleting = null"><v-card title="حذف حساب الدفع"><v-card-text>سيختفي الحساب من خيارات الدفع الجديدة. تبقى مراجع المعاملات السابقة محفوظة للاسترداد والمطابقة.</v-card-text><v-card-actions><v-btn @click="deleting = null">تراجع</v-btn><v-btn color="error" :loading="busy" @click="remove">تأكيد الحذف</v-btn></v-card-actions></v-card></v-dialog>
  </div>
</template>
<script setup>
import { computed, onMounted, ref } from 'vue'
import api from '@/modules/store/api/storeClient'
import { storePayload } from '@/modules/store/utils/checkoutSession'
const gateways=ref([]), drivers=ref([]), dialog=ref(false), form=ref({}), configured=ref({}), busy=ref(false), error=ref(''), deleting=ref(null)
const definition=computed(()=>drivers.value.find(d=>d.id===form.value.driver))
const labels={api_key:'مفتاح API',hmac_secret:'سر توقيع HMAC',integration_id:'معرف التكامل',iframe_id:'معرف صفحة الدفع',secret_key:'المفتاح السري',webhook_secret:'سر توقيع Webhook',publishable_key:'المفتاح العام',merchant_id:'معرف التاجر',payment_api_key:'مفتاح API للدفع'}
async function run(task){if(busy.value)return;busy.value=true;error.value='';try{await task()}catch(e){error.value=Object.values(e.response?.data?.errors||{}).flat().join('، ')||e.response?.data?.message||'تعذر حفظ حساب الدفع'}finally{busy.value=false}}
async function fetchGateways(){const data=storePayload(await api.get('/payment-gateways'));gateways.value=Array.isArray(data)?data:(data?.data||[])}
async function load(){await run(async()=>{drivers.value=storePayload(await api.get('/payment-gateway-drivers'));await fetchGateways()})}
function edit(gateway){form.value=gateway?{id:gateway.id,name:gateway.name,driver:gateway.driver,is_active:gateway.is_active,is_test_mode:gateway.is_test_mode,is_default:gateway.is_default,config:{...(gateway.config||{})}}:{name:'',driver:drivers.value[0]?.id,is_active:false,is_test_mode:true,is_default:false,config:{}};configured.value=gateway?.credentials_configured||{};dialog.value=true}
async function save(){await run(async()=>{const data={...form.value,config:{...form.value.config},is_default:form.value.is_active&&form.value.is_default};await api[form.value.id?'put':'post']('/payment-gateways'+(form.value.id?'/'+form.value.id:''),data);dialog.value=false;await fetchGateways()})}
async function setDefault(gateway){await run(async()=>{await api.patch('/payment-gateways/'+gateway.id+'/set-default');await fetchGateways()})}
async function remove(){await run(async()=>{await api.delete('/payment-gateways/'+deleting.value.id);deleting.value=null;await fetchGateways()})}
onMounted(load)
</script>
